            Some(rest) => home.join(rest),
            None => PathBuf::from(p),
        })
        .collect();
    // Then the PATH and other usual installs (a choice of this rebuild).
    if let Some(p) = std::env::var_os("PATH") {
        candidates.extend(std::env::split_paths(&p).map(|d| d.join("claude")));
